#app .pomo {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 14px 12px;
  overflow: auto;
}

#app .tabs {
  align-self: center;
  display: flex;
  gap: 2px;
  padding: 3px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 9px;
}
#app .tab {
  background: transparent;
  border: 0;
  color: var(--muted);
  font: inherit;
  font-size: 12.5px;
  padding: 4px 16px;
  border-radius: 7px;
  cursor: pointer;
  transition: background .15s, color .15s;
}
#app .tab:hover { color: var(--text); background: var(--panel-hi); }
#app .tab.active { color: var(--text); background: rgba(var(--accent-rgb), .2); }
#app .pomo[data-mode="break"] .tab.active { background: color-mix(in srgb, var(--ok) 20%, transparent); }

#app .dial {
  flex: 1;
  min-height: 120px;
  position: relative;
  display: grid;
  place-items: center;
  container-type: size;
}
#app .dial svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
#app .dial .track {
  fill: none;
  stroke: var(--border);
  stroke-width: 5;
}
#app .dial .prog {
  fill: none;
  stroke: var(--accent);
  stroke-width: 5;
  stroke-linecap: round;
  transition: stroke-dashoffset .35s linear, stroke .3s;
}
#app .pomo[data-mode="break"] .dial .prog { stroke: var(--ok); }

#app .readout {
  position: relative;
  text-align: center;
  line-height: 1.1;
  pointer-events: none;
}
#app .time {
  font-size: 34px;
  font-size: clamp(22px, 19cqmin, 54px);
  font-weight: 300;
  font-variant-numeric: tabular-nums;
  letter-spacing: .5px;
  color: var(--text);
}
#app .sub {
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}
#app .pomo.paused .time { color: var(--muted); }

#app .checkin {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  background: rgba(var(--accent-rgb), .12);
  border: 1px solid rgba(var(--accent-rgb), .35);
}
#app .checkin[hidden] { display: none; }
#app .checkin[data-status="ok"] {
  background: color-mix(in srgb, var(--ok) 12%, transparent);
  border-color: color-mix(in srgb, var(--ok) 35%, transparent);
}
#app .checkin[data-status="slip"] {
  background: color-mix(in srgb, var(--warn) 12%, transparent);
  border-color: color-mix(in srgb, var(--warn) 35%, transparent);
}
#app .ci-text {
  font-size: 12.5px;
  color: var(--text);
  overflow-wrap: anywhere;
}
#app .ci-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}
#app .checkin:not([data-status="ask"]) .ci-actions { display: none; }

#app .controls {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
#app #pomo-toggle { min-width: 116px; }

/* settings view */
#app .settings {
  display: none;
  flex: 1;
  min-height: 0;
  flex-direction: column;
  gap: 10px;
}
#app .pomo.show-settings .settings { display: flex; }
#app .pomo.show-settings .tabs,
#app .pomo.show-settings .dial,
#app .pomo.show-settings .checkin,
#app .pomo.show-settings .controls { display: none; }

#app .set-title {
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .6px;
}
#app .set-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--text);
  font-size: 13px;
}
#app .set-row select { width: auto; min-width: 0; }
#app .set-row input[type="checkbox"] {
  width: 16px;
  height: 16px;
  accent-color: var(--accent);
  cursor: pointer;
}
#app label.set-row { cursor: pointer; }
#app .num {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
}
#app .num input {
  width: 64px;
  box-sizing: border-box;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
#app .presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
#app .chip {
  font: inherit;
  font-size: 12px;
  padding: 3px 10px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--muted);
  cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
}
#app .chip:hover { background: var(--panel-hi); color: var(--text); }
#app .chip.active {
  color: var(--text);
  background: rgba(var(--accent-rgb), .2);
  border-color: rgba(var(--accent-rgb), .45);
}
#app .hint {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.4;
  color: var(--faint);
}
#app .warn-hint { color: var(--warn); }
#app .warn-hint:empty { display: none; }
#app .set-actions {
  margin-top: auto;
  display: flex;
  justify-content: flex-end;
}

#app .today {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}
#app .dots {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-width: 45%;
}
#app .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1px solid var(--faint);
  box-sizing: border-box;
}
#app .dot.done { background: var(--accent); border-color: var(--accent); }
#app .dot.gap { margin-left: 4px; }
#app .count {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#app #pomo-sound,
#app #pomo-settings { color: var(--faint); flex: none; }
#app #pomo-sound:hover,
#app #pomo-settings:hover { color: var(--text); }
#app .pomo.show-settings #pomo-settings { color: var(--accent); }

