const root = document.querySelector('#app .pomo');
const $ = (s) => root.querySelector(s);
const timeEl = $('.time');
const subEl = $('.sub');
const progEl = $('.dial .prog');
const toggleBtn = $('#pomo-toggle');
const resetBtn = $('#pomo-reset');
const skipBtn = $('#pomo-skip');
const soundBtn = $('#pomo-sound');
const settingsBtn = $('#pomo-settings');
const dotsEl = $('.dots');
const countEl = $('.count');
const ciEl = $('.checkin');
const ciText = $('.ci-text');
const focusIn = $('#pomo-focus-len');
const breakIn = $('#pomo-break-len');
const checkSel = $('#pomo-check');
const desktopCb = $('#pomo-desktop');
const applyHint = $('#pomo-apply-hint');

const KEY = 'pomodoro';
const MIN = 60 * 1000;
const CIRC = 2 * Math.PI * 52;
const CHECK_OPTIONS = [0, 5, 10, 15, 20, 30];
const CHECK_GRACE_MS = 2 * MIN; // unanswered check-in -> reminder

const pad = (n) => String(n).padStart(2, '0');
const localDate = (ts) => {
  const d = new Date(ts);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};
const fmt = (ms) => {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${pad(s % 60)}`;
};
const fmtMins = (mins) => {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return h ? `${h}h${m ? ' ' + m + 'm' : ''}` : `${m}m`;
};
const clampInt = (v, lo, hi, def) => {
  const n = Math.round(Number(v));
  return Number.isFinite(n) && String(v).trim() !== '' ? Math.min(hi, Math.max(lo, n)) : def;
};
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const isObj = (o) => o && typeof o === 'object' && !Array.isArray(o);

const SOUND_ON = '<svg width="16" height="16" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5L6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M18.5 5.5a9 9 0 0 1 0 13"/></svg>';
const SOUND_OFF = '<svg width="16" height="16" viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5L6 9H3v6h3l5 4z"/><path d="M16 9l6 6"/><path d="M22 9l-6 6"/></svg>';

// ---- state ----
const state = {
  mode: 'focus',
  endAt: null,
  total: 25 * MIN,
  remaining: 25 * MIN,
  focusMin: 25,
  breakMin: 5,
  checkEvery: 10,
  checks: 0,
  sound: true,
  desktop: true,
  sessions: {},
  minutes: {},
  slips: {},
};
const durOf = (m) => (m === 'break' ? state.breakMin : state.focusMin) * MIN;
const otherMode = (m) => (m === 'focus' ? 'break' : 'focus');

let notice = '';
let checkin = null; // { status: 'ask'|'ok'|'slip', at, reminded, msg }
let ciTimer = null;

// Load saved state (with a timeout so the widget never hangs on boot)
let saved = null;
try {
  saved = await Promise.race([
    Promise.resolve(overlay.storage.get(KEY)).catch(() => null),
    new Promise((r) => setTimeout(() => r(null), 3000)),
  ]);
} catch (e) { saved = null; }

if (isObj(saved)) {
  state.focusMin = clampInt(saved.focusMin, 1, 180, 25);
  state.breakMin = clampInt(saved.breakMin, 1, 60, 5);
  if (CHECK_OPTIONS.includes(saved.checkEvery)) state.checkEvery = saved.checkEvery;
  if (saved.mode === 'break') state.mode = 'break';
  if (typeof saved.sound === 'boolean') state.sound = saved.sound;
  if (typeof saved.desktop === 'boolean') state.desktop = saved.desktop;
  if (isObj(saved.sessions)) state.sessions = saved.sessions;
  if (isObj(saved.minutes)) state.minutes = saved.minutes;
  if (isObj(saved.slips)) state.slips = saved.slips;
  state.total = typeof saved.total === 'number' && saved.total > 0 ? saved.total : durOf(state.mode);
  state.remaining =
    typeof saved.remaining === 'number' && saved.remaining > 0 && saved.remaining <= state.total
      ? saved.remaining
      : state.total;
  if (typeof saved.endAt === 'number') state.endAt = saved.endAt;
  state.checks = clampInt(saved.checks, 0, 10000, 0);
} else {
  state.total = state.remaining = durOf(state.mode);
}

function prune(obj) {
  const keys = Object.keys(obj).sort();
  if (keys.length > 90) keys.slice(0, keys.length - 90).forEach((k) => delete obj[k]);
}
function save() {
  // Keep roughly the last 90 days of history
  prune(state.sessions);
  prune(state.minutes);
  prune(state.slips);
  try {
    const p = overlay.storage.set(KEY, state);
    if (p && typeof p.catch === 'function') p.catch(() => {});
  } catch (e) {}
}

const isRunning = () => typeof state.endAt === 'number';
const timeLeft = () => (isRunning() ? state.endAt - Date.now() : state.remaining);
const isIdle = () => !isRunning() && state.remaining >= state.total;
const today = () => {
  try { return overlay.today(); } catch (e) { return localDate(Date.now()); }
};
const todayCount = () => Number(state.sessions[today()]) || 0;

// ---- notifications ----
function pillStatus(text) {
  try {
    const p = overlay.pill.setStatus(text);
    if (p && typeof p.catch === 'function') p.catch(() => {});
  } catch (e) {}
}
function pillNotify(text, minutes) {
  try {
    const p = overlay.pill.notify(text, minutes);
    if (p && typeof p.catch === 'function') p.catch(() => {});
  } catch (e) {}
}
function desktopNotify(title, body) {
  if (!state.desktop || !('Notification' in window)) return;
  try {
    const show = () => { try { new Notification(title, { body, silent: true }); } catch (e) {} };
    if (Notification.permission === 'granted') show();
    else if (Notification.permission !== 'denied') {
      Promise.resolve(Notification.requestPermission()).then((p) => { if (p === 'granted') show(); }).catch(() => {});
    }
  } catch (e) {}
}
function alertUser(pillText, title, body, minutes) {
  pillNotify(clip(pillText, 40), minutes);
  desktopNotify(title, body);
}

// ---- sound ----
let actx = null;
function ensureAudio() {
  try {
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (actx.state === 'suspended') actx.resume();
  } catch (e) { actx = null; }
}
function tones(freqs, step, peak) {
  if (!state.sound) return;
  ensureAudio();
  if (!actx) return;
  const t0 = actx.currentTime + 0.05;
  freqs.forEach((f, i) => {
    const o = actx.createOscillator();
    const g = actx.createGain();
    o.type = 'sine';
    o.frequency.value = f;
    const t = t0 + i * step;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(peak, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    o.connect(g).connect(actx.destination);
    o.start(t);
    o.stop(t + 1);
  });
}
const chime = () => tones([880, 1174.66, 1318.51], 0.18, 0.18);
const ping = () => tones([659.25, 987.77], 0.14, 0.12);

// ---- actions ----
function start() {
  ensureAudio();
  notice = '';
  state.endAt = Date.now() + state.remaining;
  pillNotify('');
  save();
  render();
}
function pause() {
  state.remaining = Math.max(1000, state.endAt - Date.now());
  state.endAt = null;
  if (checkin && checkin.status === 'ask') clearCheckin();
  save();
  render();
}
function reset() {
  state.endAt = null;
  state.total = durOf(state.mode);
  state.remaining = state.total;
  state.checks = 0;
  clearCheckin();
  save();
  render();
}
function setMode(m) {
  state.mode = m;
  notice = '';
  reset();
}
function complete(silent) {
  const wasFocus = state.mode === 'focus';
  if (wasFocus) {
    const day = localDate(state.endAt || Date.now());
    state.sessions[day] = (Number(state.sessions[day]) || 0) + 1;
    state.minutes[day] = (Number(state.minutes[day]) || 0) + Math.round(state.total / MIN);
  }
  state.mode = otherMode(state.mode);
  state.endAt = null;
  state.total = durOf(state.mode);
  state.remaining = state.total;
  state.checks = 0;
  clearCheckin();
  notice = wasFocus ? 'Nice work. Time for a break.' : 'Break over. Ready to focus?';
  save();
  if (!silent) {
    chime();
    if (wasFocus) alertUser('Focus done. Take a break', 'Focus session done', `Nice work. Take a ${state.breakMin} minute break.`, 5);
    else alertUser('Break over. Back to focus', 'Break over', `Ready for ${state.focusMin} more minutes of focus?`, 5);
  }
  render();
}
function toggle() {
  if (isRunning()) pause();
  else start();
}

// ---- focus check-ins ----
function clearCheckin() {
  clearTimeout(ciTimer);
  checkin = null;
  renderCheckin();
}
function maybeCheckIn() {
  if (!isRunning() || state.mode !== 'focus') return;

  if (checkin && checkin.status === 'ask') {
    if (!checkin.reminded && Date.now() - checkin.at > CHECK_GRACE_MS) {
      checkin.reminded = true;
      ping();
      alertUser('Back to focus?', 'Still focusing?', 'You missed a check-in. Get back to work.', 5);
    }
    return;
  }

  if (!state.checkEvery) return;
  const elapsed = state.total - timeLeft();
  const due = Math.floor(elapsed / (state.checkEvery * MIN));
  if (due > state.checks && timeLeft() > MIN) {
    state.checks = due;
    save();
    clearTimeout(ciTimer);
    checkin = { status: 'ask', at: Date.now(), reminded: false };
    renderCheckin();
    ping();
    alertUser('Check-in: still on task?', 'Focus check-in', 'Still on task?', 3);
  }
}
function answerCheckin(onTask) {
  if (!checkin || checkin.status !== 'ask') return;
  clearTimeout(ciTimer);
  if (onTask) {
    checkin = { status: 'ok', msg: 'Nice. Keep going.' };
    pillNotify('');
  } else {
    const day = today();
    state.slips[day] = (Number(state.slips[day]) || 0) + 1;
    save();
    checkin = { status: 'slip', msg: 'Logged. Close the distraction and get back to work.' };
    pillNotify('Back to focus', 3);
    lastDotsKey = '';
  }
  renderCheckin();
  render();
  ciTimer = setTimeout(clearCheckin, 5000);
}
function renderCheckin() {
  if (!checkin || state.mode !== 'focus') {
    ciEl.hidden = true;
    return;
  }
  ciEl.hidden = false;
  ciEl.dataset.status = checkin.status;
  ciText.textContent = checkin.status === 'ask' ? 'Still on task?' : checkin.msg;
}

// ---- settings ----
function updatePresets() {
  root.querySelectorAll('.chip').forEach((c) => {
    c.classList.toggle('active', Number(c.dataset.f) === state.focusMin && Number(c.dataset.b) === state.breakMin);
  });
}
function updateApplyHint() {
  applyHint.textContent = isIdle() ? '' : 'The current session keeps its length. New lengths apply from the next session or after Reset.';
}
function fillSettings() {
  focusIn.value = state.focusMin;
  breakIn.value = state.breakMin;
  checkSel.value = String(state.checkEvery);
  desktopCb.checked = state.desktop;
  updatePresets();
  updateApplyHint();
}
function applySettings() {
  state.focusMin = clampInt(focusIn.value, 1, 180, state.focusMin);
  state.breakMin = clampInt(breakIn.value, 1, 60, state.breakMin);
  const c = Number(checkSel.value);
  if (CHECK_OPTIONS.includes(c)) state.checkEvery = c;
  state.desktop = desktopCb.checked;
  focusIn.value = state.focusMin;
  breakIn.value = state.breakMin;
  // An untouched timer picks up the new length right away
  if (isIdle()) {
    state.total = durOf(state.mode);
    state.remaining = state.total;
    state.checks = 0;
  }
  save();
  updatePresets();
  updateApplyHint();
  render();
}
function openSettings() {
  fillSettings();
  root.classList.add('show-settings');
}
function closeSettings() {
  applySettings();
  root.classList.remove('show-settings');
}

// ---- render ----
let lastDotsKey = '';
let lastPill = null;
let lastFocusing = null, lastFocusPing = 0;

function renderDots(count) {
  const day = today();
  const mins = Number(state.minutes[day]) || count * 25;
  const slips = Number(state.slips[day]) || 0;
  const key = `${count}|${mins}|${slips}`;
  if (key === lastDotsKey) return;
  lastDotsKey = key;
  const MAX = 12;
  const slots = Math.min(MAX, Math.max(4, Math.ceil(count / 4) * 4));
  dotsEl.innerHTML = '';
  for (let i = 0; i < slots; i++) {
    const d = document.createElement('span');
    d.className = 'dot' + (i < count ? ' done' : '') + (i > 0 && i % 4 === 0 ? ' gap' : '');
    dotsEl.appendChild(d);
  }
  const slipText = slips ? ` · ${slips} slip${slips === 1 ? '' : 's'}` : '';
  if (count === 0) {
    countEl.textContent = 'No sessions yet today' + slipText;
  } else {
    countEl.textContent = `${count} session${count === 1 ? '' : 's'} · ${fmtMins(mins)}${slipText}`;
  }
  countEl.title = countEl.textContent;
}

function render() {
  const running = isRunning();
  const left = timeLeft();
  const total = state.total;
  const paused = !running && state.remaining < total;
  const label = state.mode === 'focus' ? 'Focus' : 'Break';

  root.dataset.mode = state.mode;
  root.classList.toggle('paused', paused);
  root.querySelectorAll('.tab').forEach((t) => t.classList.toggle('active', t.dataset.mode === state.mode));

  const text = fmt(left);
  if (timeEl.textContent !== text) timeEl.textContent = text;

  const progress = Math.min(1, Math.max(0, 1 - left / total));
  progEl.style.strokeDashoffset = String(CIRC * (1 - progress));

  let sub;
  if (running) sub = state.mode === 'focus' ? 'Focusing' : 'On a break';
  else if (paused) sub = 'Paused';
  else sub = notice || (state.mode === 'focus' ? 'Ready to focus' : `Take ${state.breakMin}`);
  if (subEl.textContent !== sub) subEl.textContent = sub;

  const btnText = running ? 'Pause' : paused ? 'Resume' : `Start ${label.toLowerCase()}`;
  if (toggleBtn.textContent !== btnText) toggleBtn.textContent = btnText;
  skipBtn.title = state.mode === 'focus' ? 'Skip to break' : 'Skip to focus';
  resetBtn.disabled = !running && !paused;

  const count = todayCount();
  renderDots(count);

  // Tell Cloak while a focus session runs (for its on-task checks), with a ping every 30 s so it ends if this closes.
  const focusing = running && state.mode === 'focus';
  if (focusing !== lastFocusing || (focusing && Date.now() - lastFocusPing > 30000)) {
    lastFocusing = focusing;
    lastFocusPing = Date.now();
    try { const f = overlay.focus && overlay.focus(focusing); if (f && typeof f.catch === 'function') f.catch(() => {}); } catch (e) {}
  }

  let pill = '';
  if (running) pill = `${label} ${text}`;
  else if (paused) pill = `${label} paused ${text}`;
  else if (count > 0) pill = `${count} pomodoro${count === 1 ? '' : 's'} today`;
  pill = clip(pill, 40);
  if (pill !== lastPill) {
    lastPill = pill;
    pillStatus(pill);
  }
}

function renderSound() {
  soundBtn.innerHTML = state.sound ? SOUND_ON : SOUND_OFF;
  soundBtn.title = state.sound ? 'Sound on' : 'Sound off';
}

// ---- events ----
toggleBtn.addEventListener('click', toggle);
resetBtn.addEventListener('click', () => { notice = ''; reset(); });
skipBtn.addEventListener('click', () => setMode(otherMode(state.mode)));
root.querySelector('.tabs').addEventListener('click', (e) => {
  const tab = e.target.closest('.tab');
  if (tab && tab.dataset.mode !== state.mode) setMode(tab.dataset.mode);
});
soundBtn.addEventListener('click', () => {
  state.sound = !state.sound;
  if (state.sound) ensureAudio();
  save();
  renderSound();
});
settingsBtn.addEventListener('click', () => {
  if (root.classList.contains('show-settings')) closeSettings();
  else openSettings();
});
$('#pomo-done').addEventListener('click', closeSettings);
focusIn.addEventListener('change', applySettings);
breakIn.addEventListener('change', applySettings);
checkSel.addEventListener('change', applySettings);
desktopCb.addEventListener('change', () => {
  applySettings();
  if (state.desktop && 'Notification' in window) {
    try {
      if (Notification.permission === 'default') Promise.resolve(Notification.requestPermission()).catch(() => {});
    } catch (e) {}
  }
});
[focusIn, breakIn].forEach((inp) => inp.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); applySettings(); }
}));
root.querySelector('.presets').addEventListener('click', (e) => {
  const chip = e.target.closest('.chip');
  if (!chip) return;
  focusIn.value = chip.dataset.f;
  breakIn.value = chip.dataset.b;
  applySettings();
});
$('#ci-ok').addEventListener('click', () => answerCheckin(true));
$('#ci-slip').addEventListener('click', () => answerCheckin(false));

document.addEventListener('keydown', (e) => {
  if (e.code !== 'Space') return;
  if (root.classList.contains('show-settings')) return;
  const tag = (e.target && e.target.tagName) || '';
  if (/INPUT|TEXTAREA|SELECT|BUTTON/.test(tag) || (e.target && e.target.isContentEditable)) return;
  e.preventDefault();
  toggle();
});

// ---- boot ----
progEl.style.strokeDasharray = String(CIRC);
// A session that ended while the widget was closed still counts, without a chime
if (isRunning() && Date.now() >= state.endAt) complete(true);
renderSound();
render();

setInterval(() => {
  if (isRunning() && Date.now() >= state.endAt) complete(false);
  else {
    maybeCheckIn();
    render();
  }
}, 250);
